package com.nextcandle.ai; public final class AdaptiveModel {private final double[]w=new double[FeatureVector.SIZE];private double b=0;private int samples=0;public AdaptiveModel(){w[0]=.8;w[6]=.55;w[7]=.35;w[10]=.55;w[11]=.35;w[15]=.7;w[16]=-.7;w[17]=.45;w[21]=.25;}public double predict(FeatureVector f){double z=b;for(int i=0;i<w.length;i++)z+=w[i]*f.x[i];return Maths.sigmoid(z);}public void update(FeatureVector f,boolean up,double lr){double p=predict(f),e=(up?1:0)-p;for(int i=0;i<w.length;i++)w[i]+=lr*e*f.x[i];b+=lr*e;samples++;}public int samples(){return samples;}}
